export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  maxNights: number;
  maxGuests: number;
  minNights?: number;
  minNightsError?: string;
  baseRate: number;
  highRate: number;
  extraGuestFee: number;
  fixedFee: number;
}

// Each category is the same quote with different numbers. Dispatch the
// category up front and let the numbers fall out of the lookup.
const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { name: "standard", maxNights: 14, maxGuests: 2, baseRate: 80,  highRate: 30,  extraGuestFee: 0,   fixedFee: 0 },
  suite:    { name: "suite",    maxNights: 21, maxGuests: 4, baseRate: 150, highRate: 60,  extraGuestFee: 25,  fixedFee: 0 },
  villa:    { name: "villa",    maxNights: 28, maxGuests: 8, minNights: 3, minNightsError: "villa minimum stay", baseRate: 300, highRate: 120, extraGuestFee: 0, fixedFee: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  if (!Number.isInteger(req.nights) || (req.nights as number) < 1 || (req.nights as number) > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (cfg.minNights !== undefined && (req.nights as number) < cfg.minNights) {
    return { ok: false, error: cfg.minNightsError };
  }
  if (!Number.isInteger(req.guests) || (req.guests as number) < 1 || (req.guests as number) > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyalty = req.loyaltyYears as number;

  let total = cfg.baseRate * nights;
  if (req.season === "high") {
    total += cfg.highRate * nights;
  }
  if (loyalty >= 3 || req.coupon === "VIP") {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += cfg.extraGuestFee;
  }
  total += cfg.fixedFee;

  const policy = loyalty >= 3 || req.coupon === "VIP" ? "flex" : "strict";
  const line = `${cfg.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

